convention.template:
/*******************************************************************************
* Node: <NodeName>_Compute
* Module Name: <NodeName>_Compute
*
* Description: <What this module does>
*
* Ver    Author    Date        Description
* ===    ======    ====        ===========
* 1      <author>  DD/MM/YYYY  Initial
********************************************************************************/
CREATE COMPUTE MODULE <NodeName>_Compute
  CREATE FUNCTION Main() RETURNS BOOLEAN
  BEGIN
    -- implementation
    RETURN TRUE;
  END;

  CREATE PROCEDURE CopyMessageHeaders() BEGIN
    DECLARE I INTEGER 1;
    DECLARE J INTEGER;
    SET J = CARDINALITY(InputRoot.*[]);
    WHILE I < J DO
      SET OutputRoot.*[I] = InputRoot.*[I];
      SET I = I + 1;
    END WHILE;
  END;

  CREATE PROCEDURE CopyEntireMessage() BEGIN
    SET OutputRoot = InputRoot;
  END;
END MODULE;

convention.rule:
For anticipated errors (business validation failures), set the fault code and
      message in Environment variables before throwing:
        SET Environment.Variables.SOAPFault.faultcode = 'SVC001';
        SET Environment.Variables.SOAPFault.faultstring = 'Policy not found';
        THROW USER EXCEPTION VALUES('Description');
